static knownTeams (used by the \"Add team\" datalist) went\nstale the moment the table stopped reading from it, so it''s now derived\nfrom live records in TeamAdminView and threaded into RowDetailSlideOver\nas a prop instead.","tree":{"sha":"735d449f71fdc7f87085162eb0bdf222f98886c5","url":"https://api.github.com/repos/adithiB/atlas/git/trees/735d449f71fdc7f87085162eb0bdf222f98886c5"},"url":"https://api.github.com/repos/adithiB/atlas/git/commits/6bb681fdf4c0bf8eab229bd019059c8b12c8ab54","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/83456549?v=4","events_url":"https://api.github.com/users/adithiB/events{/privacy}","followers_url":"https://api.github.com/users/adithiB/followers","following_url":"https://api.github.com/users/adithiB/following{/other_user}","gists_url":"https://api.github.com/users/adithiB/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/adithiB","id":83456549,"login":"adithiB","node_id":"MDQ6VXNlcjgzNDU2NTQ5","organizations_url":"https://api.github.com/users/adithiB/orgs","received_events_url":"https://api.github.com/users/adithiB/received_events","repos_url":"https://api.github.com/users/adithiB/repos","site_admin":false,"starred_url":"https://api.github.com/users/adithiB/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/adithiB/subscriptions","type":"User","url":"https://api.github.com/users/adithiB","user_view_type":"public"},"html_url":"https://github.com/adithiB/atlas/commit/6bb681fdf4c0bf8eab229bd019059c8b12c8ab54","node_id":"C_kwDOTKuufNoAKDZiYjY4MWZkZjRjMGJmOGVhYjIyOWJkMDE5MDU5YzhiMTJjOGFiNTQ","parents":[{"html_url":"https://github.com/adithiB/atlas/commit/b2e0c89a2f90a5687a5e77f3dea6c46cdd75a641","sha":"b2e0c89a2f90a5687a5e77f3dea6c46cdd75a641","url":"https://api.github.com/repos/adithiB/atlas/commits/b2e0c89a2f90a5687a5e77f3dea6c46cdd75a641"}],"sha":"6bb681fdf4c0bf8eab229bd019059